/** Indexes of a label list, e.g. `0 | 1 | 2` */
type Index<T extends readonly unknown[]> = {
	[K in keyof T]: K extends `${infer N extends number}` ? N : never;
}[number];

// Output stores these properties as an index into their label list. Index 0
// is "" (unset), so it never appears in output. Each enum names those indexes
// (`SkillType.BasicAttack`); `<Name>Labels[value]` gives the display text.
// Beware `SkillType[value]` is the enum reverse mapping: the member name, not
// the label. `Color` instead indexes the `<cN>…</c>` tags in rich text, short
// for `<span style="color: …">…</span>`.

