/** Expands a description's `<cN>…</c>` tags back to `<span style="color: …">…</span>` */
export function expandRichText(text: string): string {
	return text
		.replace(/<c(\d+)>/g, (_, i: string) => `<span style="color: ${Color[Number(i)]}">`)
		.replace(/<\/c>/g, "</span>");
}
